"use client"

import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Switch } from "@atlas/ui-web/primitives/Switch/Switch"
import { mockSubmit } from "../../_shared/mockApi"
import { ORDER_TOTAL, type PaymentStepProps } from "../schema"

const digits = (v: string) => v.replace(/\D/g, "")
const formatCard = (v: string) => digits(v).slice(0, 16).replace(/(.{4})/g, "$1 ").trim()
const formatExpiry = (v: string) => {
  const d = digits(v).slice(0, 4)
  return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d
}

type Errors = { cardNumber?: string; expiry?: string; cvc?: string }

function validate(d: { cardNumber: string; expiry: string; cvc: string }): Errors {
  const errors: Errors = {}
  if (digits(d.cardNumber).length !== 16) errors.cardNumber = "Enter the 16-digit card number."
  const month = Number(d.expiry.slice(0, 2))
  if (d.expiry.length !== 5 || month < 1 || month > 12) errors.expiry = "Enter a valid expiry, MM/YY."
  if (digits(d.cvc).length < 3) errors.cvc = "Enter the 3-digit security code."
  return errors
}

const column: React.CSSProperties = { display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }

export function Payment({ data, patch, next }: PaymentStepProps) {
  const [busy, setBusy] = useState(false)
  const [errors, setErrors] = useState<Errors>({})

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    const found = validate(data)
    setErrors(found)
    if (Object.keys(found).length > 0) return
    setBusy(true)
    const kind = data.simulateTimeout ? "timeout" : "declined"
    try {
      await mockSubmit(data, {
        delayMs: data.simulateTimeout ? 3000 : 1500,
        failRate: 1,
        errorMessage: kind,
      })
    } catch {
      patch({ failure: kind })
      setBusy(false)
      next()
    }
  }

  return (
    <form
      onSubmit={submit}
      noValidate
      aria-busy={busy}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-5)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
      }}
    >
      <h1
        style={{
          margin: 0,
          fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          lineHeight: "var(--atlas-line-height-tight)",
          color: "var(--atlas-foreground)",
        }}
      >
        Payment
      </h1>

      <div style={column}>
        <Label htmlFor="pe-card" required size="md">Card number</Label>
        <Input
          id="pe-card"
          size="lg"
          inputMode="numeric"
          autoComplete="cc-number"
          placeholder="1234 5678 9012 3456"
          value={data.cardNumber}
          invalid={!!errors.cardNumber}
          aria-describedby={errors.cardNumber ? "pe-card-err" : undefined}
          disabled={busy}
          onChange={(e) => patch({ cardNumber: formatCard(e.target.value) })}
        />
        {errors.cardNumber && <FieldError id="pe-card-err">{errors.cardNumber}</FieldError>}
      </div>

      <div style={{ display: "flex", gap: "var(--atlas-spacing-3)" }}>
        <div style={{ ...column, flex: 1 }}>
          <Label htmlFor="pe-expiry" required size="md">Expiry</Label>
          <Input
            id="pe-expiry"
            size="lg"
            inputMode="numeric"
            autoComplete="cc-exp"
            placeholder="MM/YY"
            value={data.expiry}
            invalid={!!errors.expiry}
            aria-describedby={errors.expiry ? "pe-expiry-err" : undefined}
            disabled={busy}
            onChange={(e) => patch({ expiry: formatExpiry(e.target.value) })}
          />
          {errors.expiry && <FieldError id="pe-expiry-err">{errors.expiry}</FieldError>}
        </div>
        <div style={{ ...column, flex: 1 }}>
          <Label htmlFor="pe-cvc" required size="md">CVC</Label>
          <Input
            id="pe-cvc"
            size="lg"
            inputMode="numeric"
            autoComplete="cc-csc"
            placeholder="123"
            value={data.cvc}
            invalid={!!errors.cvc}
            aria-describedby={errors.cvc ? "pe-cvc-err" : undefined}
            disabled={busy}
            onChange={(e) => patch({ cvc: digits(e.target.value).slice(0, 4) })}
          />
          {errors.cvc && <FieldError id="pe-cvc-err">{errors.cvc}</FieldError>}
        </div>
      </div>

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "baseline",
          paddingBlock: "var(--atlas-spacing-3)",
          borderBlockStart: "var(--atlas-border-width-1) solid var(--atlas-border-subtle)",
        }}
      >
        <span style={{ fontSize: "var(--atlas-text-body)", color: "var(--atlas-foreground-muted)" }}>Order total</span>
        <span
          style={{
            fontSize: "var(--atlas-text-h3)",
            fontWeight: "var(--atlas-font-weight-semibold)",
            color: "var(--atlas-foreground)",
          }}
        >
          {ORDER_TOTAL}
        </span>
      </div>

      <Button type="submit" variant="primary" size="lg" loading={busy} style={{ inlineSize: "100%" }}>
        {busy ? "Processing…" : "Pay now"}
      </Button>

      <div
        style={{
          paddingBlockStart: "var(--atlas-spacing-3)",
          borderBlockStart: "var(--atlas-border-width-1) dashed var(--atlas-border)",
        }}
      >
        <Switch
          size="sm"
          label="Simulate network timeout"
          description="Prototype control. Off: the card is declined."
          checked={data.simulateTimeout}
          disabled={busy}
          onCheckedChange={(simulateTimeout) => patch({ simulateTimeout })}
        />
      </div>
    </form>
  )
}

function FieldError({ id, children }: { id: string; children: React.ReactNode }) {
  return (
    <span id={id} style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-danger)" }}>
      {children}
    </span>
  )
}
